import bundle from "./generated/overview-media.json" with { type: "json" };

// Overview images: task frames read from the published simulation clips, condition frames and
// figures from the manuscript (Fig. 2–4). Generated by scripts/capture-overview-media.mjs,
// which records each file's source and SHA-256; never edit by hand.

type Image = { image: string; width: number; height: number; sha256: string };
export type TaskMedia = Image & { clip: string; frameAt: number };
export type ConditionMedia = Image & { source: string; sourceSha256: string };
export type FigureMedia = Image & { source: string; sourceSha256: string };

const media = bundle as unknown as {
  tasks: Record<string, TaskMedia>;
  conditions: Record<string, ConditionMedia>;
  figures: Record<"tracks" | "hybrid", FigureMedia>;
};

export const taskMedia = (taskId: string): TaskMedia | null => media.tasks[taskId] ?? null;
export const conditionMedia = (domain: "sim" | "real", condition: string): ConditionMedia | null => media.conditions[`${domain}:${condition}`] ?? null;
export const figureMedia = media.figures;
